189	+   Mỗi slot một dù màu riêng (multiParams.colors[slot]), dựng lần đầu slot có người (sync) rồi tái dùng; hình học dùng chung, vật liệu riêng.
190	+   Vị trí nhận 5 lần/s được nội suy, lấy mẫu chậm interpSends chu kỳ để luôn có hai mẫu kẹp. Slot đổi chủ (đổi tên, hoặc từ trống sang có người)
191	+   thì xóa mẫu cũ và ẩn dù tới khi có mẫu đầu, nên dù người mới không trượt từ chỗ người cũ. Không cấp phát mỗi khung (D-018). */
192	+import * as THREE from 'three';
193	+import { scene } from '../../core/renderer';
194	+import { CONFIG } from '../../config';
195	+import { exBuildGlider, exPlaceGlider } from '../glider';
196	+import type { GliderState } from '../flight';
197	+import { ExTrack, type ExPose } from './interp';
198	+import type { Flyer } from './protocol';
199	+
200	+const M = CONFIG.explore.multi;
201	+
202	+interface RemoteSlot {
203	+  name: string | null;        // null = slot trống
204	+  group: THREE.Group | null;
205	+  track: ExTrack;
206	+  pose: ExPose;               // đệm lấy mẫu
207	+  state: GliderState;         // trạng thái trả cho exPlaceGlider và slotState
208	+  live: boolean;              // đã có mẫu và đang hiện
209	+}
210	+
211	+const slots: RemoteSlot[] = Array.from({ length: M.slots }, () => ({
212	+  name: null, group: null, track: new ExTrack(), pose: { x: 0, y: 0, z: 0, yaw: 0, bank: 0 },
213	+  state: { pos: new THREE.Vector3(), yaw: 0, bank: 0, ret: 0, speed: 0 }, live: false
214	+}));
215	+let me = -1;
216	+
217	+function hide(s: RemoteSlot): void {
218	+  s.track.reset(); s.live = false;
219	+  if (s.group) s.group.visible = false;
220	+}
221	+
222	+export const exRemotes = {
223	+  /* Danh sách người bay đổi (sảnh, vào, ra): dựng dù cho slot mới, đặt lại slot đổi chủ, ẩn slot trống */
224	+  sync(flyers: Flyer[], mySlot: number): void {
225	+    me = mySlot;
226	+    for (let i = 0; i < slots.length; i++) {
227	+      const s = slots[i];
228	+      let name: string | null = null;
229	+      if (i !== mySlot) for (const f of flyers) if (f.slot === i) { name = f.name; break; }
230	+      if (name === null) { s.name = null; hide(s); continue; }
231	+      if (name !== s.name) {
232	+        s.name = name; hide(s);
233	+        if (!s.group) { s.group = exBuildGlider(M.colors[i % M.colors.length]); s.group.visible = false; scene.add(s.group); }
234	+      }
235	+    }
236	+  },
237	+
238	+  /* Gói vị trí gộp: f = [slot, x, y, z, yaw, bank]; chỉ nhận slot đã biết chủ và không phải của mình */
239	+  onPos(f: number[][], nowMs: number): void {
240	+    for (const e of f) {
241	+      const i = e[0], s = slots[i];
242	+      if (!s || i === me || s.name === null) continue;
243	+      s.track.push(nowMs, e[1], e[2], e[3], e[4], e[5]);
244	+    }
245	+  },
246	+
247	+  update(nowMs: number): void {
248	+    const t = nowMs - M.interpSends * 1000 / M.sendHz;
249	+    for (const s of slots) {
250	+      if (s.name === null || !s.group) continue;
251	+      if (!s.track.sample(t, s.pose)) { s.live = false; s.group.visible = false; continue; }
252	+      const p = s.pose;
253	+      s.state.pos.set(p.x, p.y, p.z); s.state.yaw = p.yaw; s.state.bank = p.bank;
254	+      exPlaceGlider(s.group, s.state);
255	+      s.group.visible = s.live = true;
256	+    }
257	+  },
258	+
259	+  /* Trạng thái đã nội suy của dù ở slot (cho nhãn tên); null nếu chưa có hoặc slot trống */
260	+  slotState(slot: number): GliderState | null {
261	+    const s = slots[slot];
262	+    return s && s.live ? s.state : null;
263	+  },
264	+
265	+  /* Rời phòng: ẩn hết, quên tên (dù đã dựng giữ lại để tái dùng) */
266	+  clear(): void {
267	+    me = -1;
268	+    for (const s of slots) { s.name = null; hide(s); }
269	+  }
270	+};
