139	+const N = 8, W = 6;   // số mẫu tối đa; số trường mỗi mẫu
140	+export interface ExPose { x: number; y: number; z: number; yaw: number; bank: number }
141	+
142	+export class ExTrack {
143	+  private buf = new Float64Array(N * W);
144	+  private head = 0;      // chỉ số ô sẽ ghi tiếp
145	+  private n = 0;         // số mẫu đang có
146	+  get count(): number { return this.n; }
147	+
148	+  push(t: number, x: number, y: number, z: number, yaw: number, bank: number): void {
149	+    if (this.n > 0 && t <= this.buf[((this.head + N - 1) % N) * W]) return;   // mẫu cũ hoặc trùng giờ: bỏ để giữ thứ tự
150	+    const o = this.head * W, b = this.buf;
151	+    b[o] = t; b[o + 1] = x; b[o + 2] = y; b[o + 3] = z; b[o + 4] = yaw; b[o + 5] = bank;
152	+    this.head = (this.head + 1) % N;
153	+    if (this.n < N) this.n++;
154	+  }
155	+
156	+  /* Ghi vị trí tại thời điểm t vào out; false nếu chưa có mẫu */
157	+  sample(t: number, out: ExPose): boolean {
158	+    if (this.n === 0) return false;
159	+    const b = this.buf, first = (this.head + N - this.n) % N * W;
160	+    const last = ((this.head + N - 1) % N) * W;
161	+    let a = first, c = first;
162	+    if (t >= b[last]) a = c = last;
163	+    else if (t > b[first]) {
164	+      for (let i = 0; i < this.n - 1; i++) {
165	+        const p = (first + i * W) % (N * W), q = (p + W) % (N * W);
166	+        if (t <= b[q]) { a = p; c = q; break; }
167	+      }
168	+    }
169	+    const k = a === c ? 0 : (t - b[a]) / (b[c] - b[a]);
170	+    out.x = b[a + 1] + (b[c + 1] - b[a + 1]) * k;
171	+    out.y = b[a + 2] + (b[c + 2] - b[a + 2]) * k;
172	+    out.z = b[a + 3] + (b[c + 3] - b[a + 3]) * k;
173	+    let dy = b[c + 4] - b[a + 4];
174	+    dy -= Math.round(dy / (2 * Math.PI)) * 2 * Math.PI;
175	+    out.yaw = b[a + 4] + dy * k;
